var n=`0630-ful-medames`;var a=`world-0630`;var t=`EG`;var s=`northern-africa`;var o=4;var r=567;var l={en:`Ful Medames`,ua:`Фуль медамес`};var d={en:`Ful Medames is a Egypt classic prepared with fava beans, garlic, lemon juice, parsley. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Start from dried fava beans, soaked and thoroughly cooked, rather than ready-cooked ful beans.`,ua:`Фуль медамес, страва кухні країни Єгипет зі складниками: боби фава, часник, лимонний сік, петрушка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Використано сухі боби фава, які попередньо замочують і повністю проварюють, замість готових консервованих.`};var m=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`fava-beans`,400,`g`],[`water`,850,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 70 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 70 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:70,i:[[`water`,900,`ml`]]},{en:`Mash some of the fully cooked fava beans with a little hot water, then fold in garlic, lemon, cumin and olive oil; keep a rustic texture.`,ua:`Розімніть частину повністю зварених бобів із невеликою кількістю гарячої води, додайте часник, лимон, кмин і олію, зберігаючи грубу текстуру.`,t:[`mixing`],m:7,i:[[`water`,160,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`garlic`,3,`clove`],[`ground-cumin`,5,`g`],[`lemon-juice`,45,`ml`],[`extra-virgin-olive-oil`,65,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`],[`tomato`,180,`g`]]}];var g={slug:n,id:a,country:`EG`,region:s,servings:4,minutes:567,title:l,text:d,steps:m};export{t as country,g as default,a as id,r as minutes,s as region,o as servings,n as slug,m as steps,d as text,l as title};